= useTelemetry()\n  if (!telemetry) return\n  const flow = ssoFlowStore.start(\n    trigger === 'customer_create' ? 'cloud_customer_create' : surface,\n    presentation === 'redirect'\n  )\n  telemetry.trackSsoEvent({\n    name: SSO_TELEMETRY_EVENT.requiredShown,\n    properties: { ...flowProperties(flow), trigger, presentation }\n  })\n}\n\nexport function trackSsoContinueClicked(surface: SsoSurface): void {\n  const telemetry = useTelemetry()\n  if (!telemetry) return\n  const flow = ssoFlowStore.markContinued(surface)\n  telemetry.trackSsoEvent({\n    name: SSO_TELEMETRY_EVENT.continueClicked,\n    properties: flowProperties(flow)\n  })\n}\n\nexport function trackSsoSignInFailed(\n  reason: SsoSignInFailureReason,\n  surface: SsoSurface\n): void {\n  const telemetry = useTelemetry()\n  if (!telemetry) return\n  const flow = ssoFlowStore.finish() ?? createSsoFlow(surface)\n  telemetry.trackSsoEvent({\n    name: SSO_TELEMETRY_EVENT.signInFailed,\n    properties: { ...flowProperties(flow), reason }\n  })\n}\n\n/** An SSO session after an attempt this tab continued is that attempt's sign-in. */\nexport function trackSsoSignInCompleted(): void {\n  const flow = ssoFlowStore.finish()\n  if (!flow?.continued) return\n  signedInFlow = flow\n  useTelemetry()?.trackSsoEvent({\n    name: SSO_TELEMETRY_EVENT.signInCompleted,\n    properties: flowProperties(flow)\n  })\n}\n\n/** The SSO-required screen closed without the person continuing. */\nexport function abandonSsoFlow(): void {\n  ssoFlowStore.abandon()\n}\n\n/** Another sign-in method completed, so no SSO attempt is in flight. */\nexport function endSsoFlow(): void {\n  ssoFlowStore.finish()\n}\n\nexport function trackSsoWorkspaceLanded(\n  landedInDefaultWorkspace: boolean\n): void {\n  const flow = signedInFlow\n  signedInFlow = undefined\n  if (!flow) return\n  useTelemetry()?.trackSsoEvent({\n    name: SSO_TELEMETRY_EVENT.workspaceLanded,\n    properties: {\n      ...flowProperties(flow),\n      landed_in_default_workspace: landedInDefaultWorkspace\n    }\n  })\n}\n","import { onUnmounted, readonly, shallowRef } from 'vue'\n\nimport type {\n  SsoRequiredTrigger,\n  SsoSurface\n} from '@comfyorg/account-core/telemetry'\n\nimport type { SsoRequiredContext } from '@/platform/auth/sso/ssoRequired'\nimport {\n  abandonSsoFlow,\n  trackSsoRequiredShown\n} from '@/platform/auth/sso/ssoTelemetry'\n\nconst hostSurfaces: SsoSurface[] = []\nconst notice = shallowRef<SsoRequiredContext>()\n\n/**\n * Shows the refusal on the auth page that hosts it, in that page's brand\n * design system, instead of the app-styled shared dialog. False without one.\n */\nexport function presentInline(\n  context: SsoRequiredContext,\n  trigger: SsoRequiredTrigger\n): boolean {\n  const surface = hostSurfaces.at(-1)\n  if (!surface) return false\n  if (!notice.value) trackSsoRequiredShown(surface, trigger, 'notice')\n  notice.value = { ...notice.value, ...context }\n  return true\n}\n\n/** Makes the calling auth page the place an SSO refusal is shown. */\nexport function useSsoRequiredInlineHost(surface: SsoSurface) {\n  hostSurfaces.push(surface)\n  onUnmounted(() => {\n    hostSurfaces.splice(hostSurfaces.lastIndexOf(surface), 1)\n    if (notice.value) abandonSsoFlow()\n    notice.value = undefined\n  })\n  return { notice: readonly(notice) }\n}\n","import { omitBy } from 'es-toolkit'\n\nimport type { SsoRequiredTrigger } from '@comfyorg/account-core/telemetry'\nimport {\n  isAccountOutsideOrganizationRefusal,\n  isSsoRequiredRefusal,\n  ssoRequiredOrganizationId\n} from '@comfyorg/account-core/sso'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { t } from '@/i18n'\nimport {\n  ACCOUNT_OUTSIDE_ORGANIZATION_DIALOG_KEY,\n  SSO_REQUIRED_DIALOG_KEY\n} from '@/platform/auth/sso/ssoRequiredDialogKey'\nimport { presentInline } from '@/platform/auth/sso/ssoRequiredInline'\nimport {\n  abandonSsoFlow,\n  trackSsoRequiredShown\n} from '@/platform/auth/sso/ssoTelemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nexport interface SsoRequiredContext {\n  readonly email?: string\n  /** Where SSO sends the person back; the current page when absent. */\n  readonly returnTo?: string\n  /** The organization the refusal names; its SSO, not the email's. */\n  readonly organizationId?: string\n}\n\n/**\n * Shows the one SSO-required screen. False while `sso_enabled` is off, so the\n * caller keeps the handling it has today. Several refusals can land at once;\n * a later caller only adds what it knows, so a request seam without context\n * never erases the email the sign-in page passed. A refusal always answers the\n * organization, so one that names none clears an earlier one.\n */\nexport function presentSsoRequired(\n  trigger: SsoRequiredTrigger,\n  context: SsoRequiredContext = {}\n): boolean {\n  if (!useFeatureFlags().flags.ssoEnabled) return false\n  const dialogStore = useDialogStore()\n  const known = {\n    ...omitBy(context, (value) => value === undefined),\n    ...('organizationId' in context && {\n      organizationId: context.organizationId\n    })\n  }\n  if (presentInline(known, trigger)) return true\n  void import('@/platform/auth/sso/SsoRequiredDialogContent.vue')\n    .then(({ default: component }) => {\n      if (dialogStore.isDialogOpen(SSO_REQUIRED_DIALOG_KEY)) {\n        dialogStore.updateDialog({\n          key: SSO_REQUIRED_DIALOG_KEY,\n          contentProps: known\n        })\n        return\n      }\n      trackSsoRequiredShown('cloud_app', trigger, 'notice')\n      dialogStore.showDialog({\n        key: SSO_REQUIRED_DIALOG_KEY,\n        component,\n        props: known,\n        dialogComponentProps: {\n          headless: true,\n          onClose: abandonSsoFlow\n        }\n      })\n    })\n    .catch((error: unknown) => {\n      reportError(error, {\n        surface: 'auth',\n        errorType: 'failure_loading_sso_required_dialog'\n      })\n      useToast().error(t('auth.sso.required.title'), {\n        description: t('auth.sso.required.body')\n      })\n    })\n  return true\n}\n\nfunction presentAccountOutsideOrganization(): boolean {\n  if (!useFeatureFlags().flags.ssoEnabled) return false\n  const dialogStore = useDialogStore()\n  if (dialogStore.isDialogOpen(ACCOUNT_OUTSIDE_ORGANIZATION_DIALOG_KEY)) {\n    return true\n  }\n  void import('@/platform/auth/sso/SsoAccountOutsideOrganizationDialogContent.vue')\n    .then(({ default: component }) => {\n      dialogStore.showDialog({\n        key: ACCOUNT_OUTSIDE_ORGANIZATION_DIALOG_KEY,\n        component,\n        dialogComponentProps: {\n          headless: true\n        }\n      })\n    })\n    .catch((error: unknown) => {\n      reportError(error, {\n        surface: 'auth',\n        errorType: 'failure_loading_sso_outside_organization_dialog'\n      })\n      useToast().error(t('auth.sso.outsideOrganization.title'), {\n        description: t('auth.sso.outsideOrganization.body')\n      })\n    })\n  return true\n}\n\n/** A Cloud API request whose credential the organization refused. */\nexport function presentForRefusal(status: number, body: unknown): boolean {\n  if (isAccountOutsideOrganizationRefusal(status, body)) {\n    return presentAccountOutsideOrganization()\n  }\n  return (\n    isSsoRequiredRefusal(status, body) &&\n    presentSsoRequired('api_key', {\n      organizationId: ssoRequiredOrganizationId(body)\n    })\n  )\n}\n\n/** Reads a clone, and only of a 403 while `sso_enabled` is on. */\nexport async function presentForResponse(response: Response): Promise<boolean> {\n  if (response.status !== 403 || !useFeatureFlags().flags.ssoEnabled) {\n    return false\n  }\n  const body: unknown = await response\n    .clone()\n    .json()\n    .catch(() => undefined)\n  return presentForRefusal(response.status, body)\n}\n"],"file":"ssoRequired-MIfrr8G3.js"}"""

